css:
ul,ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img,svg,video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button,input,select,textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote,figure,fieldset{margin:revert;padding:revert}
h1,h2,h3,h4,h5,h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}

:root{
  --white:#FFFFFF; --paper:#F6F9F7; --sage:#E2EDE6; --sage-2:#CBDED3;
  --forest:#143A32; --forest-2:#0B2620; --moss:#1F5A4C;
  --gold:#B07A17; --gold-ink:#7C550F; --gold-lift:#E0B45F;
  --coral:#C2543C; --coral-ink:#9B3E26; --coral-lift:#E89478;
  --ink:#14201C; --ink-70:#3D4B46; --ink-45:#566159;
  --rev:#D9E6DF; --rev-70:#AEC4BA;
  --rule:#B9CFC3; --rule-rev:#3A5A51;
  --serif:ui-serif,"New York","Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,"Times New Roman",serif;
  --sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue","Noto Sans",Arial,sans-serif;
  --r-btn:999px; --r-field:8px; --r-box:14px; --r-img:10px;
  --pad:clamp(52px,6.4vw,104px);
  --gut:clamp(18px,4vw,40px);
  --shadow:0 1px 2px rgba(20,58,50,.05),0 10px 28px -12px rgba(20,58,50,.18);
  --shadow-lg:0 2px 4px rgba(11,38,32,.06),0 24px 56px -22px rgba(11,38,32,.32);
}

*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--white);color:var(--ink);font-family:var(--sans);
  font-size:17px;line-height:1.62;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img,svg{max-width:100%}
img{display:block;height:auto}
h1,h2,h3,h4{font-family:var(--serif);font-weight:600;line-height:1.1;letter-spacing:-.012em;
  margin:0;color:var(--ink);text-wrap:balance}
h1{font-size:clamp(38px,5.0vw,66px);line-height:1.04;letter-spacing:-.022em}
h2{font-size:clamp(28px,3.3vw,45px);letter-spacing:-.018em}
h3{font-size:clamp(20px,1.6vw,24px);letter-spacing:-.008em}
h4{font-size:18px}
p{margin:0 0 18px}
p:last-child{margin-bottom:0}
em{font-style:normal;color:var(--gold-ink)}
a{color:var(--moss);text-underline-offset:3px;text-decoration-thickness:1px}
a:hover{color:var(--forest)}
ul,ol{margin:0;padding:0}
.wrap{width:100%;max-width:1240px;margin:0 auto;padding:0 var(--gut)}
.skip{position:absolute;left:-9999px;top:0;background:var(--forest);color:#fff;padding:12px 20px;z-index:100}
.skip:focus{left:8px;top:8px}
:focus-visible{outline:3px solid var(--gold);outline-offset:3px;border-radius:3px}
.svgdefs{position:absolute;width:0;height:0;overflow:hidden}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms!important;transition-duration:.001ms!important;
    scroll-behavior:auto!important}
}

/* ---------------------------------------------------------------- surfaces */
.sec{padding:var(--pad) 0;position:relative}
.sec--white{background:var(--white)}
.sec--paper{background:var(--paper)}
.sec--sage{background:var(--sage)}
.sec--forest{background:var(--forest);color:var(--rev)}
.sec--forest h2,.sec--forest h3,.sec--forest h4{color:#fff}
.sec--forest a{color:var(--gold-lift)}
.sec--forest em{color:var(--gold-lift)}
.sec--sage + .sec--sage,.sec--paper + .sec--paper{padding-top:0}
.edge{border-top:1px solid var(--rule)}

/* ---------------------------------------------------------------- type bits */
.cue{font-family:var(--sans);font-size:12px;font-weight:700;letter-spacing:.15em;
  text-transform:uppercase;color:var(--gold-ink);margin:0 0 16px;display:flex;align-items:center;gap:12px}
.cue::before{content:"";width:26px;height:2px;background:var(--gold);flex:none;border-radius:2px}
.sec--forest .cue{color:var(--gold-lift)}
.sec--forest .cue::before{background:var(--gold-lift)}
.sec-head{max-width:760px;margin:0 0 clamp(34px,3.6vw,56px)}
.sec-head .lede{font-size:clamp(17px,1.25vw,19px);color:var(--ink-70);margin:18px 0 0;max-width:66ch}
.sec--forest .sec-head .lede{color:var(--rev-70)}
.sec-head--wide{max-width:none;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.92fr);
  gap:clamp(24px,4vw,64px);align-items:end}
.sec-head--wide .lede{margin:0}
.lede{font-size:clamp(17px,1.25vw,19px);color:var(--ink-70)}

/* ---------------------------------------------------------------- buttons */
.btn,.btn-o,.btn-q{display:inline-flex;align-items:center;gap:10px;font-family:var(--sans);
  font-size:15px;font-weight:600;letter-spacing:.005em;padding:14px 26px;border-radius:var(--r-btn);
  text-decoration:none;border:1.5px solid transparent;cursor:pointer;transition:transform .16s ease,
  background .16s ease,border-color .16s ease,color .16s ease;line-height:1.2}
.btn{background:var(--forest);color:#fff;border-color:var(--forest)}
.btn:hover{background:var(--forest-2);border-color:var(--forest-2);color:#fff;transform:translateY(-1px)}
.btn-o{background:transparent;color:var(--forest);border-color:var(--rule)}
.btn-o:hover{border-color:var(--forest);color:var(--forest);background:rgba(20,58,50,.04)}
.btn-q{background:transparent;color:var(--forest);border-color:transparent;padding-left:4px;padding-right:4px}
.btn-q:hover{color:var(--gold-ink)}
.btn svg,.btn-o svg,.btn-q svg{width:17px;height:17px;flex:none;transition:transform .16s ease}
.btn:hover svg,.btn-o:hover svg{transform:translateX(3px)}
.sec--forest .btn,.cta .btn{background:var(--gold-lift);color:#0B2620;border-color:var(--gold-lift)}
.sec--forest .btn:hover,.cta .btn:hover{background:#EEC97E;border-color:#EEC97E;color:#0B2620}
.sec--forest .btn-o,.cta .btn-o{color:#fff;border-color:var(--rule-rev)}
.sec--forest .btn-o:hover,.cta .btn-o:hover{border-color:var(--rev);background:rgba(255,255,255,.07);color:#fff}
.btnrow{display:flex;flex-wrap:wrap;gap:12px;align-items:center}

/* ---------------------------------------------------------------- header */
.site-header{position:sticky;top:0;z-index:60;background:rgba(255,255,255,.94);
  backdrop-filter:saturate(1.4) blur(10px);border-bottom:1px solid transparent;transition:border-color .2s}
.site-header[data-stuck="1"]{border-bottom-color:var(--rule);box-shadow:0 10px 24px -20px rgba(20,58,50,.5)}
.hdr{display:flex;align-items:center;gap:clamp(14px,2.4vw,40px);min-height:74px}
.hdr .brandlink{display:flex;align-items:center;flex:none;text-decoration:none}
.nav{flex:1;min-width:0}
.nav > ul{display:flex;list-style:none;gap:2px;margin:0;padding:0}
.nav-item{position:static}
.nav-btn{display:inline-flex;align-items:center;gap:6px;background:none;border:0;cursor:pointer;
  font:inherit;font-size:15px;font-weight:500;color:var(--ink-70);padding:10px 13px;border-radius:8px;
  font-family:var(--sans)}
.nav-btn:hover{color:var(--forest);background:var(--sage)}
.nav-btn[aria-expanded="true"]{color:var(--forest);background:var(--sage)}
.nav-btn .cv{width:14px;height:14px;transition:transform .18s ease;opacity:.7}
.nav-btn[aria-expanded="true"] .cv{transform:rotate(180deg)}
.mega{position:absolute;left:0;right:0;top:100%;background:var(--white);
  border-top:1px solid var(--rule);border-bottom:1px solid var(--rule);box-shadow:var(--shadow-lg)}
.mega-in{max-width:1240px;margin:0 auto;padding:34px var(--gut) 40px;display:grid;
  grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:28px 34px}
.mega h3{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.14em;
  text-transform:uppercase;color:var(--gold-ink);margin:0 0 14px}
.mega ul{list-style:none}
.mega li + li{margin-top:9px}
.mega a{color:var(--ink);text-decoration:none;font-size:15px;display:inline-block;
  border-bottom:1px solid transparent}
.mega a:hover{color:var(--forest);border-bottom-color:var(--gold)}
.hdr-cta{display:flex;align-items:center;gap:10px;flex:none;margin-left:auto}
.hdr-cta .btn{padding:11px 20px;font-size:14px}
.burger{display:none;background:none;border:1.5px solid var(--rule);border-radius:10px;
  width:44px;height:44px;align-items:center;justify-content:center;cursor:pointer;color:var(--forest)}
.burger svg{width:20px;height:20px}
.mnav{border-top:1px solid var(--rule);background:var(--white);max-height:78vh;overflow:auto;
  padding:8px 0 24px}
.mnav details{border-bottom:1px solid var(--rule)}
.mnav summary{list-style:none;cursor:pointer;padding:15px 2px;font-weight:600;font-size:16px;
  display:flex;align-items:center;justify-content:space-between;color:var(--ink)}
.mnav summary::-webkit-details-marker{display:none}
.mnav summary .cv{width:16px;height:16px;opacity:.6;transition:transform .18s}
.mnav details[open] summary .cv{transform:rotate(180deg)}
.mnav .mg{padding:0 0 16px}
.mnav .mg h4{font-family:var(--sans);font-size:11px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--gold-ink);margin:12px 0 8px}
.mnav .mg a{display:block;padding:8px 0;color:var(--ink-70);text-decoration:none;font-size:15px}
.mnav .mg a:hover{color:var(--forest)}
.mcta{display:grid;gap:10px;margin-top:20px}
.mcta .btn,.mcta .btn-o{justify-content:center}

/* ---------------------------------------------------------------- artwork */
.plate{display:block;position:relative;overflow:hidden;border-radius:var(--r-img);
  background:var(--sage-2);isolation:isolate}
.plate > img,.plate > svg{width:100%;height:100%;display:block;object-fit:cover}
.plate--21x9{aspect-ratio:21/9} .plate--16x9{aspect-ratio:16/9}
.plate--3x2{aspect-ratio:3/2} .plate--4x3{aspect-ratio:4/3} .plate--1x1{aspect-ratio:1/1}
.plate--4x5{aspect-ratio:4/5} .plate--3x4{aspect-ratio:3/4} .plate--5x7{aspect-ratio:5/7}
.plate--fill{height:100%}
.plate--fill > svg{position:absolute;inset:0;height:100%}
.plate--ring{box-shadow:0 0 0 1px rgba(20,58,50,.10)}

/* ---------------------------------------------------------------- hero */
.hero{position:relative;background:var(--forest-2);color:var(--rev);overflow:hidden;
  padding:clamp(40px,5vw,76px) 0 clamp(52px,6vw,92px)}
.hero-bg{position:absolute;inset:0;z-index:0;opacity:.55}
.hero-bg svg{width:100%;height:100%;object-fit:cover}
.hero::after{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;
  background:linear-gradient(104deg,#0B2620 0%,rgba(11,38,32,.90) 40%,rgba(11,38,32,.34) 72%,rgba(11,38,32,.55) 100%)}
.hero .wrap{position:relative;z-index:2}
.hero-in{display:grid;grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);
  gap:clamp(30px,4.4vw,72px);align-items:center}
.hero .cue{color:var(--gold-lift)}
.hero .cue::before{background:var(--gold-lift)}
.hero h1{color:#fff;max-width:16ch}
.hero h1 em{color:var(--gold-lift);font-style:normal}
.hero-lead{font-size:clamp(17px,1.35vw,20px);color:var(--rev);margin:22px 0 30px;max-width:56ch}
.hero-badge{display:flex;gap:14px;align-items:flex-start;border:1px solid var(--rule-rev);
  border-radius:var(--r-box);padding:16px 20px;margin:0 0 28px;background:rgba(255,255,255,.045);
  max-width:520px}
.hero-badge .bdot{width:34px;height:34px;flex:none;border-radius:50%;background:rgba(224,180,95,.16);
  display:grid;place-items:center}
.hero-badge .bdot svg{width:20px;height:20px}
.hero-badge strong{display:block;font-size:14px;letter-spacing:.02em;color:#fff}
.hero-badge span{font-size:14px;color:var(--rev-70);line-height:1.5}
.hero-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin:34px 0 0;
  border-top:1px solid var(--rule-rev);list-style:none}
.hero-facts li{padding:20px 22px 0 0;position:relative}
.hero-facts li + li{padding-left:24px;border-left:1px solid var(--rule-rev)}
.hero-facts b{display:block;font-family:var(--serif);font-size:19px;font-weight:600;color:#fff;
  margin-bottom:6px;letter-spacing:-.01em}
.hero-facts span{font-size:14px;color:var(--rev-70);line-height:1.5;display:block}

.hero-art{position:relative;display:grid;grid-template-columns:repeat(12,1fr);
  grid-template-rows:auto auto;gap:14px}
.hero-art .a1{grid-column:1/9;grid-row:1/3;border-radius:var(--r-img);overflow:hidden;
  box-shadow:var(--shadow-lg)}
.hero-art .a2{grid-column:8/13;grid-row:1/2;border-radius:var(--r-img);overflow:hidden;
  box-shadow:var(--shadow-lg);align-self:start;margin-top:34px}
.hero-art .a3{grid-column:8/13;grid-row:2/3;border-radius:var(--r-img);overflow:hidden;
  box-shadow:var(--shadow-lg);align-self:end}
.hero-art .tag{position:absolute;left:-14px;bottom:26px;z-index:3;background:var(--white);
  color:var(--ink);border-radius:var(--r-btn);padding:11px 20px 11px 14px;display:flex;gap:11px;
  align-items:center;box-shadow:var(--shadow-lg);font-size:13.5px;font-weight:600;max-width:86%}
.hero-art .tag .brandmark{width:24px;height:24px;flex:none}

/* ---------------------------------------------------------------- quote section */
.qsec{background:var(--paper);position:relative;padding:var(--pad) 0}
.qsec-in{display:grid;grid-template-columns:minmax(0,.88fr) minmax(0,1.12fr);
  gap:clamp(28px,4vw,64px);align-items:start}
.qsec-aside .plate{box-shadow:var(--shadow)}
.qsec-aside .qpoints{list-style:none;margin:26px 0 0;padding:0}
.qsec-aside .qpoints li{display:flex;gap:12px;padding:13px 0;border-top:1px solid var(--rule);
  font-size:15px;color:var(--ink-70);line-height:1.5}
.qsec-aside .qpoints li:last-child{border-bottom:1px solid var(--rule)}
.qsec-aside .qpoints b{color:var(--ink);font-weight:600}
.qsec-aside .qn{font-variant-numeric:tabular-nums;font-weight:700;color:var(--gold-ink);
  font-size:13px;letter-spacing:.06em;flex:none;padding-top:2px}

/* ---------------------------------------------------------------- form */
.brief{background:var(--white);border:1px solid var(--rule);border-radius:var(--r-box);
  padding:clamp(22px,2.6vw,38px);box-shadow:var(--shadow-lg)}
.brief-head h2{font-size:clamp(24px,2.2vw,32px);margin-bottom:12px}
.brief-head p{color:var(--ink-70);font-size:15.5px}
.brief .steps{display:flex;list-style:none;gap:8px;margin:26px 0 24px;padding:0 0 18px;
  border-bottom:1px solid var(--rule);flex-wrap:wrap}
.brief .steps li{display:flex;align-items:center;gap:7px;font-size:12.5px;color:var(--ink-45);
  font-weight:500;padding:5px 11px 5px 5px;border-radius:999px}
.brief .steps .num{font-variant-numeric:tabular-nums;font-weight:700;font-size:11px;
  width:24px;height:24px;border-radius:50%;display:grid;place-items:center;
  background:var(--sage);color:var(--ink-45)}
.brief .steps li[aria-current="step"]{color:var(--forest);background:var(--sage)}
.brief .steps li[aria-current="step"] .num{background:var(--forest);color:#fff}
.brief .steps li[data-done] .num{background:var(--gold);color:#fff}
.frow{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}
.frow.one{grid-template-columns:1fr}
.field{display:flex;flex-direction:column;gap:7px;min-width:0}
.field label,.opt-lbl{font-size:13.5px;font-weight:600;color:var(--ink);letter-spacing:.005em}
.opt{font-weight:500;color:var(--ink-45);font-size:12px;margin-left:4px}
.field input,.field select,.field textarea{font:inherit;font-size:15.5px;color:var(--ink);
  background:var(--white);border:1.5px solid var(--rule);border-radius:var(--r-field);
  padding:12px 14px;width:100%;min-width:0;transition:border-color .15s,box-shadow .15s}
.field textarea{min-height:108px;resize:vertical}
.field select{appearance:none;background-image:linear-gradient(45deg,transparent 50%,#566159 50%),
  linear-gradient(135deg,#566159 50%,transparent 50%);
  background-position:calc(100% - 20px) 50%,calc(100% - 14px) 50%;
  background-size:6px 6px,6px 6px;background-repeat:no-repeat;padding-right:42px}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--forest);
  box-shadow:0 0 0 3px rgba(20,58,50,.14)}
.field input[aria-invalid="true"],.field select[aria-invalid="true"]{border-color:#9B3E26}
.picks{display:flex;flex-wrap:wrap;gap:9px}
.picks label{display:inline-flex;align-items:center;gap:9px;border:1.5px solid var(--rule);
  border-radius:999px;padding:10px 17px;font-size:14.5px;cursor:pointer;background:var(--white);
  transition:border-color .15s,background .15s}
.picks input{accent-color:#143A32;width:16px;height:16px;margin:0}
.picks label:hover{border-color:var(--moss)}
.picks label:has(input:checked){border-color:var(--forest);background:var(--sage)}
.mem{background:var(--sage);border-radius:var(--r-field);padding:16px 18px;font-size:13.5px;
  line-height:1.6;color:var(--ink-70);margin:6px 0 18px}
.mem strong{color:var(--ink)}
.consent{display:flex;gap:11px;align-items:flex-start;font-size:14px;color:var(--ink-70);
  margin-bottom:12px;line-height:1.5;cursor:pointer}
.consent input{accent-color:#143A32;width:17px;height:17px;margin:2px 0 0;flex:none}
.err{display:flex;gap:9px;align-items:center;color:#9B3E26;font-size:14px;font-weight:600;
  margin:4px 0 14px}
.err svg{width:17px;height:17px;flex:none}
.fnav{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:8px}
/* Cloudflare Turnstile is injected into this row at runtime; give it a full line of its own so the Continue and Send buttons sit underneath it rather than beside it */
.fnav .cf-turnstile{flex:0 0 100%;width:100%;order:-1;margin:0 0 4px!important}
.fnav .cf-turnstile iframe{display:block;max-width:100%}
@media (max-width:480px){.fnav>button,.fnav>label{flex:1 1 100%;justify-content:center}}

/* ------------------------------------------------------------ enquiry form steps
   The four panes are driven by four radio buttons rather than by script, so the
   form keeps working whatever happens to JavaScript on the page. The radios belong
   to an empty owner form, which keeps them out of the submitted lead data. */
.brief .stepr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;
  overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap}
.brief .pane{display:none}
#pye-step-1:checked ~ .pane[data-pane="1"],
#pye-step-2:checked ~ .pane[data-pane="2"],
#pye-step-3:checked ~ .pane[data-pane="3"],
#pye-step-4:checked ~ .pane[data-pane="4"]{display:block}

/* progress chips: clickable, with completed steps marked in gold */
.brief .steps li{padding:0}
.brief .steps li label{display:flex;align-items:center;gap:7px;padding:5px 11px 5px 5px;
  border-radius:999px;cursor:pointer}
#pye-step-2:checked ~ .steps li:nth-child(-n+1) .num,
#pye-step-3:checked ~ .steps li:nth-child(-n+2) .num,
#pye-step-4:checked ~ .steps li:nth-child(-n+3) .num{background:var(--gold);color:#fff}
#pye-step-1:checked ~ .steps li:nth-child(1) label,
#pye-step-2:checked ~ .steps li:nth-child(2) label,
#pye-step-3:checked ~ .steps li:nth-child(3) label,
#pye-step-4:checked ~ .steps li:nth-child(4) label{color:var(--forest);background:var(--sage)}
#pye-step-1:checked ~ .steps li:nth-child(1) .num,
#pye-step-2:checked ~ .steps li:nth-child(2) .num,
#pye-step-3:checked ~ .steps li:nth-child(3) .num,
#pye-step-4:checked ~ .steps li:nth-child(4) .num{background:var(--forest);color:#fff}
#pye-step-1:focus-visible ~ .steps li:nth-child(1) label,
#pye-step-2:focus-visible ~ .steps li:nth-child(2) label,
#pye-step-3:focus-visible ~ .steps li:nth-child(3) label,
#pye-step-4:focus-visible ~ .steps li:nth-child(4) label{outline:3px solid var(--gold);outline-offset:2px}

/* Back, Continue and Send: only the pair that belongs to the current step is shown */
.brief .fnav > .s-back,.brief .fnav > .s-next,.brief .fnav > .s-send{display:none}
#pye-step-1:checked ~ .fnav > .n2,
#pye-step-2:checked ~ .fnav > .b1,
#pye-step-2:checked ~ .fnav > .n3,
#pye-step-3:checked ~ .fnav > .b2,
#pye-step-3:checked ~ .fnav > .n4,
#pye-step-4:checked ~ .fnav > .b3,
#pye-step-4:checked ~ .fnav > .s-send{display:inline-flex}
.brief .fnav label{cursor:pointer;-webkit-user-select:none;user-select:none}
@media (max-width:560px){
  .brief .steps li label{font-size:11.5px;padding:4px 8px 4px 4px}
}
.fnote{font-size:13px;color:var(--ink-45);margin:16px 0 0;line-height:1.55}

/* ---------------------------------------------------------------- ladder */
.ladder{display:grid;gap:0;border-top:1px solid var(--rule)}
.rung{display:grid;grid-template-columns:auto minmax(0,1fr) minmax(0,.86fr);
  gap:clamp(18px,3vw,48px);padding:clamp(28px,3vw,44px) 0;border-bottom:1px solid var(--rule);
  align-items:start}
.rung-n{font-family:var(--serif);font-size:clamp(38px,4vw,58px);line-height:.9;font-weight:600;
  color:var(--gold-ink);font-variant-numeric:tabular-nums;min-width:1.6ch}
.rung h3{margin:0 0 12px;font-size:clamp(21px,1.9vw,27px)}
.rung p{color:var(--ink-70);margin:0}
.rung-note{margin-top:14px;font-size:14.5px;color:var(--gold-ink);font-weight:600;
  display:flex;gap:9px;align-items:flex-start}
.rung-note::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--gold);
  flex:none;margin-top:8px}
.rung ul{list-style:none;display:grid;gap:9px}
.rung ul li{position:relative;padding-left:22px;font-size:15px;color:var(--ink-70);line-height:1.5}
.rung ul li::before{content:"";position:absolute;left:0;top:9px;width:10px;height:2px;
  background:var(--moss);border-radius:2px}

/* ---------------------------------------------------------------- editorial index */
.edx{display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1.18fr);
  gap:clamp(28px,4vw,64px);align-items:start}
.edx-art{position:sticky;top:104px}
.edx-art .plate{box-shadow:var(--shadow)}
.edx-art .cap{margin:16px 0 0;font-size:14px;color:var(--ink-45);line-height:1.55}
.edx-list{border-top:1px solid var(--rule)}
.edx-row{display:grid;grid-template-columns:auto minmax(0,1fr);gap:18px;
  padding:24px 0;border-bottom:1px solid var(--rule);align-items:start;
  text-decoration:none;color:inherit;transition:background .16s}
a.edx-row:hover{background:rgba(20,58,50,.028)}
a.edx-row:hover h3{color:var(--moss)}
.edx-row .n{font-variant-numeric:tabular-nums;font-size:12px;font-weight:700;letter-spacing:.1em;
  color:var(--gold-ink);padding-top:7px;min-width:2.2ch}
.edx-row h3{margin:0 0 8px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.edx-row h3 .arw{width:17px;height:17px;color:var(--moss);transition:transform .16s}
a.edx-row:hover h3 .arw{transform:translateX(4px)}
.edx-row p{margin:0;color:var(--ink-70);font-size:15.5px}
.edx-row .go{display:inline-flex;align-items:center;gap:7px;margin-top:11px;font-size:14px;
  font-weight:600;color:var(--moss)}
.edx-row .go svg{width:15px;height:15px}
.sec--forest .edx-list,.sec--forest .edx-row{border-color:var(--rule-rev)}
.sec--forest .edx-row p{color:var(--rev-70)}

/* ---------------------------------------------------------------- mosaic */
.mosaic{display:grid;grid-template-columns:repeat(12,1fr);gap:clamp(12px,1.4vw,20px)}
.mos{position:relative;display:block;border-radius:var(--r-img);overflow:hidden;
  text-decoration:none;color:#fff;box-shadow:var(--shadow);isolation:isolate}
.mos .plate{border-radius:0}
.mos::after{content:"";position:absolute;inset:0;z-index:1;
  background:linear-gradient(to top,rgba(7,25,21,.90) 0%,rgba(7,25,21,.52) 38%,rgba(7,25,21,.06) 72%)}
.mos-txt{position:absolute;inset:auto 0 0 0;z-index:2;padding:clamp(18px,2vw,28px)}
.mos-txt h3{color:#fff;margin:0 0 8px;font-size:clamp(20px,1.8vw,26px)}
.mos-txt p{color:#DCE8E2;margin:0;font-size:14.5px;line-height:1.55;max-width:46ch}
.mos-txt .go{display:inline-flex;align-items:center;gap:8px;margin-top:14px;font-size:14px;
  font-weight:600;color:var(--gold-lift)}
.mos-txt .go svg{width:15px;height:15px;transition:transform .16s}
.mos:hover .go svg{transform:translateX(4px)}
.mos:hover .plate > svg{transform:scale(1.03)}
.mos .plate > svg{transition:transform .5s ease}
.mos--a{grid-column:span 7} .mos--b{grid-column:span 5}
.mos--c{grid-column:span 5} .mos--d{grid-column:span 7}

/* ---------------------------------------------------------------- dark split */
.dsplit{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.92fr);
  gap:clamp(28px,4.4vw,72px);align-items:start}
.dsplit .prose p{color:var(--rev);font-size:16.5px}
.dsplit .prose p + p{margin-top:18px}
.notes{display:grid;gap:16px}
.note{border:1px solid var(--rule-rev);border-radius:var(--r-box);padding:22px 24px;
  background:rgba(255,255,255,.04)}
.note h4{color:#fff;margin:0 0 8px;font-size:17px;font-family:var(--serif)}
.note p{margin:0;color:var(--rev-70);font-size:15px;line-height:1.6}
.dark-art{border-radius:var(--r-img);overflow:hidden;margin-bottom:26px;box-shadow:var(--shadow-lg)}

/* ---------------------------------------------------------------- flow */
.flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(16px,2vw,30px);
  position:relative;counter-reset:flow}
.flow::before{content:"";position:absolute;left:0;right:0;top:27px;height:2px;
  background:var(--rule);z-index:0}
.flow-step{position:relative;z-index:1;background:transparent}
.flow-step .n{width:54px;height:54px;border-radius:50%;background:var(--forest);color:#fff;
  display:grid;place-items:center;font-family:var(--serif);font-size:21px;font-weight:600;
  margin-bottom:20px;box-shadow:0 0 0 8px var(--sage);font-variant-numeric:tabular-nums}
.flow-step:nth-child(4) .n{background:var(--gold);color:#0B2620}
.flow-step h3{font-size:19px;margin:0 0 10px}
.flow-step p{margin:0;color:var(--ink-70);font-size:15px}

/* ---------------------------------------------------------------- locations */
.loc{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.06fr);
  gap:clamp(28px,4vw,64px);align-items:start}
.loc-map{border-radius:var(--r-box);overflow:hidden;box-shadow:var(--shadow);
  border:1px solid var(--rule)}
.loc-block{margin-top:clamp(34px,4vw,56px)}
.loc-block h3{margin:0 0 18px;font-size:20px}
.loc-note{margin-top:18px;font-size:14.5px;color:var(--ink-45)}
.finder{background:var(--white);border:1px solid var(--rule);border-radius:var(--r-box);
  padding:clamp(20px,2.2vw,28px);box-shadow:var(--shadow)}
.finder label{display:block;font-size:13.5px;font-weight:600;margin-bottom:8px}
.finder input{font:inherit;font-size:16px;width:100%;padding:13px 15px;border-radius:var(--r-field);
  border:1.5px solid var(--rule);background:var(--white)}
.finder input:focus{border-color:var(--forest);box-shadow:0 0 0 3px rgba(20,58,50,.14)}
.finder-out{list-style:none;margin:14px 0 0;max-height:322px;overflow:auto}
.finder-out li + li{border-top:1px solid var(--rule)}
.finder-out a{display:flex;justify-content:space-between;gap:14px;align-items:baseline;
  padding:12px 4px;text-decoration:none;color:var(--ink);font-size:15.5px;font-weight:500}
.finder-out a:hover{color:var(--moss)}
.finder-out .reg{font-size:12.5px;color:var(--ink-45);font-weight:500;text-align:right;flex:none}
.finder-none{padding:14px 4px;color:var(--ink-45);font-size:14.5px}
.chips{display:flex;flex-wrap:wrap;gap:9px;list-style:none}
.chips a{display:inline-block;padding:9px 16px;border-radius:999px;border:1px solid var(--rule);
  background:var(--white);font-size:14px;color:var(--ink);text-decoration:none;transition:.15s}
.chips a:hover{border-color:var(--forest);background:var(--forest);color:#fff}
.states{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(16px,2vw,26px)}
.state{border:1px solid var(--rule);border-radius:var(--r-box);padding:24px;background:var(--white)}
.state h4{margin:0 0 6px;font-size:19px}
.state h4 a{text-decoration:none;color:var(--ink)}
.state h4 a:hover{color:var(--moss)}
.state .maj{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0 0;list-style:none}
.state .maj a{display:inline-block;padding:7px 14px;border-radius:999px;background:var(--sage);
  color:var(--forest);font-size:13.5px;text-decoration:none;font-weight:600}
.state .maj a:hover{background:var(--forest);color:#fff}
.state .oth{margin:12px 0 0;font-size:14px;color:var(--ink-70);line-height:1.9}
.state .oth a{color:var(--ink-70);text-decoration:none;border-bottom:1px solid var(--rule)}
.state .oth a:hover{color:var(--forest);border-bottom-color:var(--gold)}
.state .sn{margin:14px 0 0;font-size:13.5px;color:var(--ink-45);line-height:1.6}

/* ---------------------------------------------------------------- faq */
.faq{max-width:880px;border-top:1px solid var(--rule)}
.faq details{border-bottom:1px solid var(--rule)}
.faq summary{list-style:none;cursor:pointer;padding:22px 44px 22px 0;position:relative;
  font-family:var(--serif);font-size:clamp(18px,1.5vw,21px);font-weight:600;color:var(--ink);
  line-height:1.35}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"";position:absolute;right:6px;top:30px;width:13px;height:13px;
  border-right:2px solid var(--gold-ink);border-bottom:2px solid var(--gold-ink);
  transform:rotate(45deg);transition:transform .2s;transform-origin:center}
.faq details[open] summary::after{transform:rotate(-135deg);top:34px}
.faq summary:hover{color:var(--moss)}
.faq .fa{padding:0 44px 24px 0;color:var(--ink-70);font-size:16px;max-width:74ch}
.faq .fa p{margin:0 0 14px}

/* ---------------------------------------------------------------- cta */
.cta{position:relative;background:var(--forest-2);color:var(--rev);overflow:hidden;
  padding:clamp(56px,6.4vw,104px) 0}
.cta-bg{position:absolute;inset:0;z-index:0;opacity:.62}
.cta-bg svg{width:100%;height:100%;object-fit:cover}
.cta::after{content:"";position:absolute;inset:0;z-index:1;
  background:radial-gradient(120% 120% at 22% 40%,rgba(11,38,32,.94) 0%,rgba(11,38,32,.80) 44%,rgba(11,38,32,.55) 100%)}
.cta .wrap{position:relative;z-index:2}
.cta-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);
  gap:clamp(28px,4vw,64px);align-items:center}
.cta h2{color:#fff;font-size:clamp(30px,3.6vw,50px);margin-bottom:18px}
.cta h2 em{color:var(--gold-lift);font-style:italic}
.cta p{color:var(--rev);font-size:17px;max-width:52ch}
.cta .fine{margin-top:22px;font-size:13.5px;color:var(--rev-70)}
.cta .btnrow{margin-top:28px}
.cta-fig .plate{box-shadow:var(--shadow-lg)}

/* ---------------------------------------------------------------- footer */
.site-footer{background:var(--forest-2);color:var(--rev-70);padding:clamp(48px,5vw,80px) 0 0;
  font-size:15px}
.site-footer h3{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.14em;
  text-transform:uppercase;color:var(--gold-lift);margin:0 0 16px}
.site-footer ul{list-style:none}
.site-footer li + li{margin-top:10px}
.site-footer a{color:var(--rev-70);text-decoration:none}
.site-footer a:hover{color:#fff}
.f-top{display:grid;grid-template-columns:minmax(0,1.35fr) repeat(3,minmax(0,1fr));
  gap:clamp(24px,3vw,48px);padding-bottom:clamp(36px,4vw,56px)}
.f-tag{font-family:var(--serif);font-size:20px;color:#fff;margin:20px 0 10px;letter-spacing:-.01em}
.f-desc{margin:0;color:var(--rev-70);max-width:38ch;font-size:14.5px}
.f-mid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(20px,2.6vw,40px);
  padding:clamp(32px,3.6vw,48px) 0;border-top:1px solid var(--rule-rev)}
.f-mid ul{font-size:14px}
.f-bot{display:flex;flex-wrap:wrap;gap:14px 26px;justify-content:space-between;align-items:center;
  padding:24px 0 28px;border-top:1px solid var(--rule-rev);font-size:13.5px}
.f-bot ul{display:flex;flex-wrap:wrap;gap:10px 22px}
.f-bot li + li{margin-top:0}

/* ---------------------------------------------------------------- misc */
.prose p{color:var(--ink-70)}
.grid{display:grid}
.crumbs{background:var(--paper);border-bottom:1px solid var(--rule);font-size:13.5px}
.crumbs ol{display:flex;flex-wrap:wrap;gap:8px;list-style:none;padding:12px 0;margin:0;
  color:var(--ink-45)}
.crumbs li + li::before{content:"/";margin-right:8px;color:var(--rule)}
.crumbs a{color:var(--ink-45);text-decoration:none}
.crumbs a:hover{color:var(--forest)}

@media (max-width:1080px){
  .hero-in{grid-template-columns:1fr;gap:40px}
  .hero h1{max-width:20ch}
  .hero-art{max-width:640px}
  .edx,.loc,.dsplit,.qsec-in,.cta-grid{grid-template-columns:1fr}
  .edx-art{position:static}
  .f-top{grid-template-columns:1fr 1fr;gap:32px}
  .f-mid{grid-template-columns:1fr 1fr}
}
@media (max-width:980px){
  .nav{display:none}
  .burger{display:inline-flex}
  .hdr-cta .btn{display:none}
  .flow{grid-template-columns:1fr 1fr;gap:30px 24px}
  .flow::before{display:none}
  .mosaic > *{grid-column:span 6}
  .states{grid-template-columns:1fr}
}
@media (max-width:760px){
  body{font-size:16.5px}
  .rung{grid-template-columns:auto minmax(0,1fr);gap:16px 20px}
  .rung ul{grid-column:2/3}
  .rung-n{font-size:34px}
  .hero-facts{grid-template-columns:1fr}
  .hero-facts li{padding:16px 0}
  .hero-facts li + li{padding-left:0;border-left:0;border-top:1px solid var(--rule-rev)}
  .sec-head--wide{grid-template-columns:1fr;gap:18px;align-items:start}
  .qsec-in{gap:34px}
  .cta-fig{order:-1}
  .f-top,.f-mid{grid-template-columns:1fr}
  .hero-art .a1{grid-column:1/13;grid-row:1/2}
  .hero-art .a2{grid-column:1/7;grid-row:2/3;margin-top:0}
  .hero-art .a3{grid-column:7/13;grid-row:2/3}
  .hero-art .tag{left:0;bottom:auto;top:-12px;position:relative;margin-bottom:2px;max-width:100%}
}
@media (max-width:620px){
  .frow{grid-template-columns:1fr}
  .mosaic > *{grid-column:span 12}
  .flow{grid-template-columns:1fr;gap:22px}
  .flow-step{display:grid;grid-template-columns:auto minmax(0,1fr);gap:16px;align-items:start}
  .flow-step .n{width:46px;height:46px;font-size:18px;margin-bottom:0;box-shadow:0 0 0 5px var(--sage)}
  .brief .steps li span.num{width:22px;height:22px}
  .btnrow{gap:10px}
  .btn,.btn-o{padding:13px 22px;font-size:14.5px}
}
@media (max-width:420px){
  :root{--gut:16px}
  .brief .steps{gap:5px}
  .brief .steps li{font-size:11.5px;padding:4px 8px 4px 4px}
  .btnrow{display:grid}
  .btnrow .btn,.btnrow .btn-o{justify-content:center;width:100%}
  .hero-art .a2,.hero-art .a3{grid-column:1/13}
  .hero-art .a2{grid-row:2/3} .hero-art .a3{grid-row:3/4}
  .faq summary{padding-right:36px;font-size:17.5px}
}
@media print{
  .site-header,.cta,.finder,.mnav{display:none}
  body{font-size:12pt}
  .sec{padding:18pt 0}
}

.cue.draw::before{width:0;transition:width .55s cubic-bezier(.2,.7,.3,1)}
.cue.draw.in::before{width:26px}

.brandlink svg{display:block;height:34px;width:auto}
.f-brand svg{display:block;height:36px;width:auto}
@media (max-width:560px){.brandlink svg{height:28px}}
@media (max-width:400px){.brandlink svg{height:24px}}
@media (max-width:360px){.brandlink svg{height:22px}}

svg.arw{width:17px;height:17px;flex:none;display:inline-block;vertical-align:middle}
.edx-row .n svg.arw{width:15px;height:15px;color:var(--gold-ink);display:block;margin-top:6px}
.site-header svg[class~="cv"]{width:14px;height:14px}

[hidden]{display:none!important}
.hero .btn{background:var(--gold-lift);color:#0B2620;border-color:var(--gold-lift)}
.hero .btn:hover{background:#EEC97E;border-color:#EEC97E;color:#0B2620}
.hero .btn-o{color:#fff;border-color:var(--rule-rev)}
.hero .btn-o:hover{border-color:var(--rev);background:rgba(255,255,255,.08);color:#fff}
.cue{align-items:flex-start}
.cue::before{margin-top:8px}
.hero-art{position:relative}
.hero-art .tag{left:16px;bottom:16px}
@media (min-width:761px){.hero-art .tag{left:-10px;bottom:18px}}
.qsec-aside .plate{margin-top:26px}
.sec-head--wide .cue{margin-bottom:14px}

/* hero markers and tagline, carried over from the approved layout */
.hero-art .a1,.hero-art .a2,.hero-art .a3{position:relative}
.marker{position:absolute;left:14px;bottom:14px;z-index:3;background:rgba(255,255,255,.94);
  color:var(--forest);border-radius:999px;padding:7px 15px;font-size:12.5px;font-weight:700;
  letter-spacing:.05em;text-transform:uppercase;box-shadow:var(--shadow)}
.hero-art .tagline{grid-column:1/13;margin:6px 0 0;font-family:var(--serif);font-size:17px;
  color:var(--rev-70);font-style:italic;text-align:right}
/* the ladder level indicator: three bars, filled to the level of help */
.rung-n{display:flex;flex-direction:column;gap:6px;min-width:46px;padding-top:8px}
.rung-n i{display:block;width:46px;height:7px;border-radius:4px;background:var(--sage-2)}
.rung-n i.on{background:var(--gold)}
/* editorial index rows */
.edx-row{display:grid;grid-template-columns:auto minmax(0,1fr);gap:18px;padding:24px 0;
  border-bottom:1px solid var(--rule);align-items:start}
.edx-row .num{font-variant-numeric:tabular-nums;font-family:var(--serif);font-size:19px;
  font-weight:600;color:var(--gold-ink);padding-top:2px;min-width:2.4ch}
.edx-row h3{margin:0 0 8px}
.edx-row p{margin:0;color:var(--ink-70);font-size:15.5px}
.edx-row .go{display:inline-flex;align-items:center;gap:8px;margin-top:12px;font-size:14.5px;
  font-weight:600;color:var(--moss);text-decoration:none}
.edx-row .go:hover{color:var(--forest)}
.edx-row .go svg{width:15px;height:15px;transition:transform .16s}
.edx-row .go:hover svg{transform:translateX(4px)}
/* compact index used for the major markets list */
.idx{border-top:1px solid var(--rule)}
.idx-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:6px 18px;
  padding:18px 4px;border-bottom:1px solid var(--rule);text-decoration:none;color:inherit;
  align-items:baseline;transition:background .16s}
.idx-row:hover{background:rgba(20,58,50,.03)}
.idx-row .num{grid-row:1/3;font-variant-numeric:tabular-nums;font-size:12px;font-weight:700;
  letter-spacing:.08em;color:var(--gold-ink);align-self:start;padding-top:5px}
.idx-row h3{margin:0;font-size:19px}
.idx-row p{grid-column:2/3;margin:0;color:var(--ink-70);font-size:14.5px}
.idx-row .arw{grid-row:1/2;color:var(--moss);transition:transform .16s}
.idx-row:hover .arw{transform:translateX(4px)}
.idx-row:hover h3{color:var(--moss)}
/* finder */
.fin{position:relative}
.fin .fic{position:absolute;left:14px;top:50%;transform:translateY(-50%);width:19px;height:19px;
  color:var(--ink-45);pointer-events:none}
.fin .fic svg{width:19px;height:19px}
.finder .fin input{padding-left:42px}
.finder-out .none{padding:14px 4px;color:var(--ink-45);font-size:14.5px;line-height:1.6}
/* states */
.state{display:grid;gap:14px}
.state .nm{font-family:var(--serif);font-size:21px;font-weight:600;letter-spacing:-.01em}
.state .nm a{color:var(--ink);text-decoration:none}
.state .nm a:hover{color:var(--moss)}
.state .lab{display:block;font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;
  color:var(--gold-ink);margin-bottom:9px}
.state .lnk{display:flex;flex-wrap:wrap;gap:8px}
.state .lnk a{display:inline-block;padding:7px 14px;border-radius:999px;background:var(--sage);
  color:var(--forest);font-size:13.5px;text-decoration:none;font-weight:600}
.state .lnk a:hover{background:var(--forest);color:#fff}
.state .also{margin:0;font-size:13.5px;color:var(--ink-45);line-height:1.6}

.note h3{color:#fff;margin:0 0 8px;font-size:17px;font-family:var(--serif)}
.edx .idx{border-top:1px solid var(--rule)}

/* closing band: one centred statement over the light field, no competing picture */
.cta-in{max-width:780px;margin:0 auto;text-align:center}
.cta-in .cue{justify-content:center}
.cta-in p{margin-left:auto;margin-right:auto}
.cta-in .btnrow{justify-content:center}
/* the compact index needs explicit placement or the arrow steals the title's column */
.idx-row{grid-template-columns:auto minmax(0,1fr) auto;align-items:start}
.idx-row .num{grid-column:1;grid-row:1/3}
.idx-row h3{grid-column:2;grid-row:1}
.idx-row p{grid-column:2;grid-row:2;margin-top:6px}
.idx-row .arw{grid-column:3;grid-row:1/3;align-self:center}
/* the hero's tall tile should hug its picture, not the row it spans */
.hero-art .a1{align-self:start}
/* the level meter reads as a level, not a stack of rules */
.rung-n{flex-direction:row;align-items:flex-end;gap:5px;min-width:auto;padding-top:14px}
.rung-n i{width:9px;border-radius:3px;background:var(--sage-2)}
.rung-n i:nth-child(1){height:13px}
.rung-n i:nth-child(2){height:21px}
.rung-n i:nth-child(3){height:29px}
.rung-n i.on{background:var(--gold)}
.sec--sage .rung-n i{background:#BACEC2}
/* the questions sit beside their heading so the band is not half empty */
#faq .wrap{display:grid;grid-template-columns:minmax(0,.72fr) minmax(0,1.28fr);
  gap:clamp(26px,4vw,64px);align-items:start}
#faq .sec-head{margin-bottom:0;position:sticky;top:104px}
#faq .faq{max-width:none}
@media (max-width:1080px){#faq .wrap{grid-template-columns:1fr}
  #faq .sec-head{position:static;margin-bottom:28px}}
/* a long location column should not stretch the footer */
@media (min-width:900px){.f-mid ul{column-count:2;column-gap:22px}
  .f-mid li{break-inside:avoid}}

.cta .cue{color:var(--gold-lift)}
.cta .cue::before{background:var(--gold-lift)}
.hero h1{font-size:clamp(36px,4.35vw,58px);max-width:18ch}
.hero-lead{margin-top:20px}
@media (min-width:1081px){.hero-in{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}}

.edx-row .go{padding:5px 0}
.site-footer li a,.f-bot a{display:inline-block;padding:4px 0}
.mos-txt .go{padding:4px 0}
.idx-row{padding-top:20px;padding-bottom:20px}

/* the mosaic caption carries its own scrim, so the type never depends on what the
   picture happens to be doing underneath it */
.mos::after{background:linear-gradient(to top,rgba(7,25,21,.92) 0%,rgba(7,25,21,.58) 42%,
  rgba(7,25,21,.10) 76%,rgba(7,25,21,0) 100%)}
.mos-txt{background:linear-gradient(to top,rgba(7,25,21,.95) 0%,rgba(7,25,21,.88) 100%)}
.mos-txt p{color:#E6EFEA}
.mos-txt .go{color:#F5E3BC}
.flow-step:nth-child(4) .n{background:var(--gold-ink);color:#fff}

.mos-txt{background:linear-gradient(to top,rgba(7,25,21,.975) 0%,rgba(7,25,21,.945) 100%)}
.mos::after{background:linear-gradient(to top,rgba(7,25,21,.94) 0%,rgba(7,25,21,.62) 40%,
  rgba(7,25,21,.12) 76%,rgba(7,25,21,0) 100%)}
.mos-txt p{color:#EAF2ED}

.field input:focus-visible,.field select:focus-visible,.field textarea:focus-visible,
.finder input:focus-visible{outline:3px solid var(--gold);outline-offset:2px}
.faq summary:focus-visible,.mnav summary:focus-visible{outline:3px solid var(--gold);
  outline-offset:2px;border-radius:6px}
.hero .btn:focus-visible,.cta .btn:focus-visible,.sec--forest .btn:focus-visible,
.hero .btn-o:focus-visible,.cta .btn-o:focus-visible{outline:3px solid #FFF;outline-offset:3px}

/* the monogram is rose gold, so the badge behind it carries a rose tint rather
   than the brass one the drawn mark used */
.hero-badge .bdot{background:rgba(233,195,183,.14);width:36px;height:36px}
.hero-badge .bdot svg{width:23px;height:27px}
.brandlink svg,.f-brand svg{height:36px;width:auto}
@media (max-width:900px){.brandlink svg{height:34px}}
@media (max-width:560px){.brandlink svg{height:32px}}
@media (max-width:400px){.brandlink svg{height:30px}}
@media (max-width:360px){.brandlink svg{height:28px}}

.hero-badge .bdot{width:30px;height:30px;border-radius:50%;flex:none;background:none;
  border:1.5px solid rgba(233,195,183,.45);position:relative;margin-top:2px}
.hero-badge .bdot::after{content:"";position:absolute;inset:8px;border-radius:50%;
  background:linear-gradient(140deg,#E9C3B7,#CC958C 55%,#D9B69A)}

/* ---------------------------------------------------------------- heroes */
.hero-copy{min-width:0}
.hero-side{min-width:0}
.hero-in--lede{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);align-items:center}
.hero--lede{padding:clamp(38px,4.4vw,68px) 0 clamp(44px,5vw,78px)}
.hero-one{border-radius:var(--r-img);overflow:hidden;box-shadow:var(--shadow-lg)}
.hero-one .plate{border-radius:var(--r-img)}
.hero-plate{display:block}
.hero--slim{padding:clamp(34px,4vw,58px) 0 clamp(36px,4.2vw,62px)}
.hero-slim-in{max-width:820px}
.hero--slim h1{max-width:20ch}
.hero--slim .hero-lead{margin-bottom:0}
.hero--slim .btnrow{margin-top:26px}
.hero--slim .hero-facts{margin-top:30px;grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:1080px){
  .hero-in--lede{grid-template-columns:1fr;gap:34px}
  .hero-one{max-width:680px}
}
@media (max-width:760px){
  .hero--slim .hero-facts{grid-template-columns:1fr}
}

/* ---------------------------------------------------------------- editorial split */
.esplit{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);
  gap:clamp(26px,4vw,64px);align-items:start}
.esplit--rev .esplit-b{order:2}
.esplit--rev .esplit-m{order:1}
.esplit-m .plate{box-shadow:var(--shadow)}
.esplit-b .prose p:first-child{font-family:var(--serif);font-size:clamp(21px,2.1vw,28px);
  line-height:1.3;letter-spacing:-.012em;color:var(--ink)}
.sec--forest .esplit-b .prose p:first-child{color:#fff}
@media (max-width:900px){
  .esplit{grid-template-columns:1fr;gap:28px}
  .esplit--rev .esplit-b,.esplit--rev .esplit-m{order:0}
  .esplit-m{max-width:520px}
}

/* ---------------------------------------------------------------- numbered features */
.feat-list{display:grid;gap:0;border-top:1px solid var(--rule)}
.feat{display:grid;grid-template-columns:auto minmax(0,1fr);gap:18px 22px;
  padding:24px 0;border-bottom:1px solid var(--rule);align-items:start}
.feat .fn{font-variant-numeric:tabular-nums;font-family:var(--serif);font-size:20px;
  font-weight:600;color:var(--gold-ink);padding-top:2px;min-width:2.2ch}
.feat h3{margin:0 0 8px}
.feat p{margin:0;color:var(--ink-70);font-size:15.5px}
.feat .go{display:inline-flex;align-items:center;gap:8px;margin-top:11px;font-size:14.5px;
  font-weight:600;color:var(--moss);text-decoration:none;padding:4px 0}
.feat .go:hover{color:var(--forest)}
.feat .go svg{width:15px;height:15px;transition:transform .16s}
.feat .go:hover svg{transform:translateX(4px)}
.sec--forest .feat-list,.sec--forest .feat{border-color:var(--rule-rev)}
.sec--forest .feat p{color:var(--rev-70)}
.sec--forest .feat .fn{color:var(--gold-lift)}
.sec--forest .feat .go{color:var(--gold-lift)}

/* ---------------------------------------------------------------- panels */
.panels{display:grid;gap:clamp(14px,1.6vw,22px)}
.panels.p2{grid-template-columns:repeat(2,minmax(0,1fr))}
.panels.p3{grid-template-columns:repeat(3,minmax(0,1fr))}
.panels.p4{grid-template-columns:repeat(4,minmax(0,1fr))}
.pnl{display:block;background:var(--white);border:1px solid var(--rule);
  border-radius:var(--r-box);padding:clamp(20px,2vw,26px);text-decoration:none;color:inherit;
  transition:border-color .16s,transform .16s,box-shadow .16s}
a.pnl:hover{border-color:var(--forest);transform:translateY(-2px);box-shadow:var(--shadow)}
.pnl h3{margin:0 0 10px;font-size:19px}
.pnl p{margin:0;color:var(--ink-70);font-size:15px}
.pnl .go{display:inline-flex;align-items:center;gap:8px;margin-top:14px;font-size:14px;
  font-weight:600;color:var(--moss)}
.pnl .go svg{width:15px;height:15px;transition:transform .16s}
a.pnl:hover .go svg{transform:translateX(4px)}
.sec--sage .pnl{background:var(--white)}
.sec--forest .pnl{background:rgba(255,255,255,.05);border-color:var(--rule-rev)}
.sec--forest .pnl h3{color:#fff}
.sec--forest .pnl p{color:var(--rev-70)}
.sec--forest .pnl .go{color:var(--gold-lift)}
.sec--forest a.pnl:hover{border-color:var(--rev)}
@media (max-width:900px){.panels.p3,.panels.p4{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:600px){.panels.p2,.panels.p3,.panels.p4{grid-template-columns:1fr}}

/* ---------------------------------------------------------------- row list */
.rowlist{border-top:1px solid var(--rule)}
.rmore{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px 18px;align-items:start;
  padding:22px 4px;border-bottom:1px solid var(--rule);text-decoration:none;color:inherit;
  transition:background .16s}
a.rmore:hover{background:rgba(20,58,50,.03)}
a.rmore:hover h3{color:var(--moss)}
.rmore h3{margin:0 0 7px;font-size:19px}
.rmore p{margin:0;color:var(--ink-70);font-size:15px}
.rmore .arw{color:var(--moss);align-self:center;transition:transform .16s}
a.rmore:hover .arw{transform:translateX(4px)}
.sec--forest .rowlist,.sec--forest .rmore{border-color:var(--rule-rev)}
.sec--forest .rmore p{color:var(--rev-70)}

/* ---------------------------------------------------------------- role cards */
.roles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(16px,2vw,28px)}
.role{display:block;text-decoration:none;color:inherit}
.role .plate{border-radius:var(--r-img);box-shadow:var(--shadow);margin-bottom:18px;
  transition:transform .3s ease}
a.role:hover .plate{transform:translateY(-3px)}
.role h3{margin:0 0 8px;font-size:20px}
.role p{margin:0;color:var(--ink-70);font-size:15px}
.role .go{display:inline-flex;align-items:center;gap:8px;margin-top:12px;font-size:14px;
  font-weight:600;color:var(--moss)}
.role .go svg{width:15px;height:15px;transition:transform .16s}
a.role:hover .go svg{transform:translateX(4px)}
.sec--forest .role p{color:var(--rev-70)}
.sec--forest .role .go{color:var(--gold-lift)}
@media (max-width:900px){.roles{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:600px){.roles{grid-template-columns:1fr}}

/* ---------------------------------------------------------------- occasion lead */
.occ-lead{display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1.18fr);
  gap:clamp(24px,3.6vw,56px);align-items:center;margin:0 0 clamp(20px,2.4vw,34px)}
.occ-h{font-size:clamp(24px,2.6vw,36px);margin:0 0 12px}
.occ-lead .plate{box-shadow:var(--shadow-lg)}
@media (max-width:900px){.occ-lead{grid-template-columns:1fr;gap:24px}}

/* ---------------------------------------------------------------- services on a location */
.svc-here{display:grid;gap:0;border-top:1px solid var(--rule)}
.svc{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px 18px;align-items:center;
  padding:20px 4px;border-bottom:1px solid var(--rule);text-decoration:none;color:inherit;
  transition:background .16s}
.svc:hover{background:rgba(20,58,50,.03)}
.svc:hover h3{color:var(--moss)}
.svc h3{margin:0;font-size:19px;grid-column:1}
.svc p{margin:6px 0 0;color:var(--ink-70);font-size:15px;grid-column:1;grid-row:2}
.svc .arw{grid-column:2;grid-row:1/3;color:var(--moss);transition:transform .16s}
.svc:hover .arw{transform:translateX(4px)}
.sec--forest .svc-here,.sec--forest .svc{border-color:var(--rule-rev)}
.sec--forest .svc p{color:var(--rev-70)}

/* ---------------------------------------------------------------- location index */
.locindex{display:grid;gap:clamp(24px,3vw,40px)}
.locgroup{border-top:1px solid var(--rule);padding-top:22px}
.locgroup-h{display:flex;align-items:baseline;justify-content:space-between;gap:16px;
  flex-wrap:wrap;margin-bottom:10px}
.locgroup-h .nm{font-family:var(--serif);font-size:clamp(21px,2vw,27px);font-weight:600;
  letter-spacing:-.012em}
.locgroup-h .nm a{color:var(--ink);text-decoration:none}
.locgroup-h .nm a:hover{color:var(--moss)}
.locgroup-h .ct{font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--gold-ink);flex:none}
.lgi{margin:0 0 18px;color:var(--ink-70);font-size:15.5px;max-width:70ch}
.locgroup .also{margin:14px 0 0;font-size:14px;color:var(--ink-45);line-height:1.65;max-width:78ch}

/* ---------------------------------------------------------------- state accordion */
.stateacc{border-top:1px solid var(--rule)}
.stateacc details{border-bottom:1px solid var(--rule)}
.stateacc summary{list-style:none;cursor:pointer;display:flex;align-items:center;
  justify-content:space-between;gap:16px;padding:20px 4px;font-family:var(--serif);
  font-size:clamp(19px,1.7vw,23px);font-weight:600;color:var(--ink);position:relative}
.stateacc summary::-webkit-details-marker{display:none}
.stateacc summary:hover{color:var(--moss)}
.stateacc summary .n{font-family:var(--sans);font-size:12px;font-weight:700;
  letter-spacing:.12em;text-transform:uppercase;color:var(--gold-ink)}
.stateacc .sbody{padding:0 4px 24px}
.stateacc .sbody p{margin:0 0 16px;color:var(--ink-70);font-size:15.5px;max-width:72ch}

/* ---------------------------------------------------------------- local footer band */
.f-local{padding:clamp(26px,3vw,40px) 0 0;border-top:1px solid var(--rule-rev)}
.locext{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px clamp(20px,3vw,44px);
  align-items:baseline}
.locext .nm{font-family:var(--serif);font-size:19px;font-weight:600;grid-row:1/3}
.locext .nm a{color:#fff;text-decoration:none}
.locext .nm a:hover{color:var(--gold-lift)}
.locext .lab{display:block;font-size:11px;font-weight:700;letter-spacing:.13em;
  text-transform:uppercase;color:var(--gold-lift);margin-bottom:8px}
.locext .lnk{display:flex;flex-wrap:wrap;gap:6px 14px}
.locext .lnk a{color:var(--rev-70);text-decoration:none;font-size:14px;padding:3px 0}
.locext .lnk a:hover{color:#fff}
@media (max-width:700px){.locext{grid-template-columns:1fr}.locext .nm{grid-row:auto;margin-bottom:6px}}

/* ---------------------------------------------------------------- footer columns */
.f-col h3{margin:0 0 16px}
.f-col ul{font-size:14.5px}

/* ---------------------------------------------------------------- figures */
.figrow{display:grid;gap:clamp(12px,1.4vw,20px);align-items:start}
.figrow--2{grid-template-columns:repeat(2,minmax(0,1fr))}
.figrow--3{grid-template-columns:repeat(3,minmax(0,1fr))}
.figrow .plate{box-shadow:var(--shadow)}
.pcap{margin:14px 0 0;font-size:13.5px;color:var(--ink-45);line-height:1.6}
.sec--forest .pcap{color:var(--rev-70)}
.photoband{border-radius:var(--r-img);overflow:hidden;box-shadow:var(--shadow-lg);
  margin:clamp(24px,3vw,40px) 0}
@media (max-width:700px){.figrow--3{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:460px){.figrow--2,.figrow--3{grid-template-columns:1fr}}

/* ---------------------------------------------------------------- sitemap */
.sitemap{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));
  gap:clamp(22px,2.6vw,40px)}
.smgroup h3{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.14em;
  text-transform:uppercase;color:var(--gold-ink);margin:0 0 14px}
.smlist{list-style:none;margin:0;padding:0}
.smlist li+li{margin-top:9px}
.smlist a{color:var(--ink);text-decoration:none;font-size:15px;
  border-bottom:1px solid transparent;padding:2px 0;display:inline-block}
.smlist a:hover{color:var(--forest);border-bottom-color:var(--gold)}

/* ---------------------------------------------------------------- tables */
.tbl{width:100%;overflow-x:auto;margin:clamp(18px,2vw,28px) 0}
.tbl table{border-collapse:collapse;width:100%;min-width:520px;font-size:15px}
.tbl caption{text-align:left;font-size:13.5px;color:var(--ink-45);margin-bottom:12px;
  line-height:1.6}
.tbl th,.tbl td{text-align:left;padding:13px 16px;border-bottom:1px solid var(--rule);
  vertical-align:top}
.tbl thead th{font-family:var(--sans);font-size:11.5px;font-weight:700;letter-spacing:.1em;
  text-transform:uppercase;color:var(--gold-ink);border-bottom:1.5px solid var(--rule);
  white-space:nowrap}
.tbl tbody th{font-weight:600;color:var(--ink)}
.tbl tbody tr:hover{background:rgba(20,58,50,.025)}
.tbl td{color:var(--ink-70)}
.sec--forest .tbl th,.sec--forest .tbl td{border-color:var(--rule-rev)}
.sec--forest .tbl td{color:var(--rev-70)}
.sec--forest .tbl tbody th{color:#fff}
.sec--forest .tbl thead th{color:var(--gold-lift)}

/* ---------------------------------------------------------------- form panes */
.pane{display:block}
.qsec-form{min-width:0}
.qs-head{margin-bottom:clamp(22px,2.4vw,34px)}

/* ---------------------------------------------------------------- small utilities */
.lead,.big{font-size:clamp(17px,1.25vw,19px);color:var(--ink-70);line-height:1.65}
.sec--forest .lead,.sec--forest .big{color:var(--rev)}
.split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(20px,3vw,44px)}
.g2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(16px,2vw,28px)}
.g3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(16px,2vw,28px)}
.mt-l{margin-top:clamp(28px,3.4vw,52px)}
.m-1{margin-top:clamp(14px,1.6vw,22px)}
.m-2{margin-top:clamp(20px,2.4vw,34px)}
.btn-sm{display:inline-flex;align-items:center;gap:8px;font-size:13.5px;font-weight:600;
  padding:9px 17px;border-radius:var(--r-btn);border:1.5px solid var(--rule);
  color:var(--forest);text-decoration:none;background:var(--white)}
.btn-sm:hover{border-color:var(--forest);color:var(--forest)}
.eyebrow{font-family:var(--sans);font-size:12px;font-weight:700;letter-spacing:.15em;
  text-transform:uppercase;color:var(--gold-ink);margin:0 0 14px}
.chips--rel{margin-top:clamp(16px,2vw,26px)}
.card{background:var(--white);border:1px solid var(--rule);border-radius:var(--r-box);
  padding:clamp(20px,2.2vw,28px)}
.prose--narrow{max-width:68ch}
.idx--full,.edx-list--full{border-top:1px solid var(--rule)}
@media (max-width:760px){.split,.g2,.g3{grid-template-columns:1fr}}
@media (max-width:900px){.g3{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* ---------------------------------------------------------------- legal and utility pages */
/* Rule 30: a legal page is for reading. No decoration, one comfortable column. */
.sec--legal .prose{max-width:74ch}
.sec--legal .prose h2{margin-top:clamp(32px,3.4vw,48px)}
.sec--legal .prose h3{margin-top:clamp(22px,2.4vw,32px)}
.sec--legal .prose p,.sec--legal .prose li{font-size:16.5px;line-height:1.75}
.sec--legal .prose ul,.sec--legal .prose ol{margin:0 0 18px;padding-left:22px}
.sec--legal .prose li{margin-bottom:8px}
.sec--legal .prose li::marker{color:var(--gold-ink)}

/* ---------------------------------------------------------------- icon sizing */
/* The arrow and chevron symbols carry no intrinsic size, so every place they appear
   is given one. Without this an inline SVG falls back to 300x150 and wrecks the row. */
a svg,button svg,summary svg,.go svg,.arw,.cv{width:16px;height:16px;flex:none}
.go svg,.svc .arw,.rmore .arw,.idx-row .arw{width:15px;height:15px}
.btn svg,.btn-o svg,.btn-q svg,.btn-sm svg{width:17px;height:17px}
.nav-btn .cv,.mnav summary .cv{width:14px;height:14px}
.hero-badge .bdot{width:30px;height:30px}
svg:not([class]):not(.svgdefs){max-width:100%}
.go{display:inline-flex;align-items:center;gap:8px;text-decoration:none;font-weight:600}

.tbl-scroll{margin:10px 0 0;font-size:13px;color:var(--ink-45)}
@media (min-width:860px){.tbl-scroll{display:none}}
.sec--forest .tbl-scroll{color:var(--rev-70)}
/* The numbered note sits above its heading rather than beside it, so the body column
   is never squeezed by the width of the number at small sizes. */
.note{display:block;min-width:0}
.note > div{min-width:0}
.note .nn{display:block;font-variant-numeric:tabular-nums;font-size:12px;font-weight:700;
  letter-spacing:.12em;color:var(--gold-lift);margin:0 0 10px}
.sec--sage .note .nn,.sec--white .note .nn,.sec--paper .note .nn{color:var(--gold-ink)}
.note h3{margin:0 0 8px}
.note p{margin:0;overflow-wrap:anywhere}

.loc-path{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:0 0 16px;
  font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;
  color:var(--rev-70);font-style:normal}
.loc-path i{font-style:normal;display:inline-flex;align-items:center;gap:8px}
.loc-path i::before{content:"";width:5px;height:5px;border-radius:50%;
  background:var(--gold-lift);display:inline-block}
.loc-path i:last-child{color:#fff}

/* ---------------------------------------------------------------- surface aware notes
   The note, the pull out and the editorial split were written for the dark band on the
   approved homepage. Across the rest of the site they also appear on white, paper and
   sage, so the light surface gets its own treatment rather than inheriting reverse type
   on a pale ground. */
.note{border:1px solid var(--rule);background:var(--white);color:var(--ink)}
.note h3,.note h4{color:var(--ink)}
.note p{color:var(--ink-70)}
.note .nn{color:var(--gold-ink)}
.sec--sage .note{background:rgba(255,255,255,.72)}
.sec--paper .note{background:var(--white)}

.sec--forest .note,.cta .note,.hero .note{background:rgba(255,255,255,.045);
  border-color:var(--rule-rev)}
.sec--forest .note h3,.sec--forest .note h4,.cta .note h3,.hero .note h3{color:#fff}
.sec--forest .note p,.cta .note p,.hero .note p{color:var(--rev-70)}
.sec--forest .note .nn,.cta .note .nn,.hero .note .nn{color:var(--gold-lift)}

.dsplit .prose p{color:var(--ink-70);font-size:16.5px}
.dsplit .prose p:first-child{font-family:var(--serif);font-size:clamp(21px,2.1vw,28px);
  line-height:1.3;letter-spacing:-.012em;color:var(--ink)}
.sec--forest .dsplit .prose p{color:var(--rev)}
.sec--forest .dsplit .prose p:first-child{color:#fff}

/* the same for the editorial index, the service rows and the location index */
.edx-row p,.idx-row p,.feat p,.svc p,.rmore p{color:var(--ink-70)}
.sec--forest .edx-row p,.sec--forest .idx-row p,.sec--forest .feat p,
.sec--forest .svc p,.sec--forest .rmore p{color:var(--rev-70)}
.sec--forest h3,.sec--forest h4,.cta h3,.cta h4{color:#fff}
.sec--forest .prose p,.sec--forest .prose li{color:var(--rev)}
.sec--forest .lgi,.sec--forest .also,.sec--forest .pcap,
.sec--forest .stateacc .sbody p{color:var(--rev-70)}
.sec--forest .locgroup,.sec--forest .locgroup-h,.sec--forest .stateacc,
.sec--forest .stateacc details,.sec--forest .svc-here,.sec--forest .svc,
.sec--forest .rowlist,.sec--forest .rmore,.sec--forest .feat-list,.sec--forest .feat,
.sec--forest .idx,.sec--forest .idx-row,.sec--forest .edx-list{border-color:var(--rule-rev)}
.sec--forest .locgroup-h .nm a,.sec--forest .stateacc summary{color:#fff}
.sec--forest .locgroup-h .ct,.sec--forest .stateacc summary .n{color:var(--gold-lift)}
.sec--forest .chips a{background:rgba(255,255,255,.07);border-color:var(--rule-rev);color:#fff}
.sec--forest .chips a:hover{background:var(--gold-lift);color:#0B2620;border-color:var(--gold-lift)}
.sec--forest .tbl-scroll{color:var(--rev-70)}

/* the region label beside a location sits at body text size on a tinted row, so it
   carries the stronger ink rather than the muted one */
.finder-out .reg{color:var(--ink-70)}

/* breadcrumb links are standalone targets, so they carry enough height to be tapped */
.crumbs a,.crumbs li{display:inline-block;padding:5px 0}
.crumbs ol{padding:9px 0}
.f-bot a,.site-footer li a{padding:5px 0;display:inline-block}

/* the state name in the footer band is a standalone link, so it is given tap height */
.locext .nm a{display:inline-block;padding:3px 0;min-height:24px}
.locext .lnk a{padding:5px 0;min-height:24px;display:inline-flex;align-items:center}

/* Every form control gets a ring, whatever wraps it. A date field in particular puts
   focus on one of its own inner parts, where :focus-visible on the outer element does
   not match, so it is given the ring on plain :focus as well. */
input:focus,select:focus,textarea:focus{border-color:var(--forest);
  box-shadow:0 0 0 3px rgba(20,58,50,.16)}
input:focus-visible,select:focus-visible,textarea:focus-visible{
  outline:3px solid var(--gold);outline-offset:2px}
input[type="date"]:focus,input[type="time"]:focus,input[type="number"]:focus{
  outline:3px solid var(--gold);outline-offset:2px}
